#!/usr/bin/env bash
# Question 1: Back up etcd. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -f "${Q1_BACKUP}"
mkdir -p "$(dirname "${Q1_BACKUP}")"
kubectl -n default create configmap "${Q1_MARKER}" --from-literal=created="$(date -Is)" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
